        raise ValueError("lambda_ must be finite and in [0, 1]")
    if not isinstance(policy, dict):
        raise TypeError("policy must be a dict")

    states = sorted(
        state
        for state in _reachable_cells(env)
        if env._cell(state) != "G"
    )
    for state, row in policy.items():
